import sympy as s
ROOT=Path(__file__).resolve().parents[3];PACKET=ROOT/'research/voevodsky/semisimple_equal_kummer_limit_forces_equal_vanishing_orders.md';PREV=ROOT/'research/voevodsky/results/total_energy_triple_relative_divisor.json';RESULT=ROOT/'research/voevodsky/results/equal_order_necessity.json';p,q,e,n=s.symbols('p q e n', nonzero=True);lam=s.symbols('lambda');RB=s.Matrix([[1,0,0],[0,0,0],[1,0,0]]);RC=s.Matrix([[0,1,1],[0,0,0],[0,1,1]]);RE=s.Matrix([[1,-1,-1],[-1,1,1],[0,0,0]]);R=p*RB+q*RC+e*RE;cp=s.factor(R.charpoly(lam).as_expr());Rbal=s.simplify(R.subs(e,(p+q)/2));M=s.simplify(Rbal-(p+q)*s.eye(3));minors=[s.factor(M.extract(I,J).det()) for I in combinations(range(3),2) for J in combinations(range(3),2)];target_minor=(p-q)*(p+q)/2;Req=R.subs({p:1,q:1,e:1});Rn=s.simplify(R.subs({p:n,q:n,e:n}));checks={'general_characteristic_polynomial':s.simplify(cp-lam*(lam-2*e)*(lam-p-q))==0,'equal_spectrum_condition':'2e=p+q' in PACKET.read_text(encoding='utf-8'),'balanced_minor_obstruction':any(s.simplify(z-target_minor)==0 for z in minors) and any(s.simplify(z+target_minor)==0 for z in minors),'positive_semisimple_forces_p_equal_q':'For positive vanishing orders' in PACKET.read_text(encoding='utf-8'),'then_e_equal':s.simplify(((p+q)/2).subs(q,p)-p)==0,'common_scaling':Rn==n*Req,'scaling_preserves_kernel':Rn.nullspace()==Req.nullspace(),'scaling_preserves_eigenspaces':(Rn-2*n*s.eye(3)).nullspace()==(Req-2*s.eye(3)).nullspace(),'authority_gate':'Existence and orientation of a geometric normal map' in PACKET.read_text(encoding='utf-8')};checks={k:bool(v) for k,v in checks.items()};result={'schema':'marici.voevodsky.equal-order-necessity.v1','packet_sha256':sha256(PACKET.read_bytes()).hexdigest(),'previous_result_sha256':sha256(PREV.read_bytes()).hexdigest(),'characteristic_polynomial':str(cp),'balanced_nonzero_two_minors':['-(p-q)(p+q)/2','(p-q)(p+q)/2'],'selected_ray':'mB=mC=mE=n>0','checks':checks,'passed':all(checks.values()),'disposition':{'equal_order':'necessary for equal semisimple nonzero spectrum','common_scale':'normal ramification remains','geometric_normal_map':'missing'}};RESULT.write_text(json.dumps(result,indent=2)+'\n',encoding='utf-8');print(json.dumps({'passed':result['passed'],'checks':checks,'disposition':result['disposition']}));raise SystemExit(0 if result['passed'] else 1)
